package io.github.diodeme.ji.cli;

import java.lang.management.ManagementFactory;
import java.util.Locale;

/** Fixed-field, secret-free startup timing emitted only by the Stage 6 cold-ready harness. */
final class StartupDiagnostics {
    private static final boolean ENABLED = Boolean.parseBoolean(
            System.getenv().getOrDefault("JI_STAGE6_STARTUP_DIAGNOSTICS", "false"));
    private static final int SAMPLE = sample();

    private StartupDiagnostics() {}

    static long start() {
        return System.nanoTime();
    }

    static void mark(String phase) {
        if (!ENABLED) return;
        emit(phase, 0);
    }

    static void duration(String phase, long startedNanos) {
        if (!ENABLED) return;
        emit(phase, Math.max(0, (System.nanoTime() - startedNanos) / 1_000_000));
    }

    private static void emit(String phase, long durationMillis) {
        System.err.printf(Locale.ROOT,
                "{\"metric\":\"hostColdStartupPhase\",\"sample\":%d,"
                        + "\"phase\":\"%s\",\"durationMillis\":%d,\"jvmUptimeMillis\":%d}%n",
                SAMPLE, phase, durationMillis, ManagementFactory.getRuntimeMXBean().getUptime());
    }

    private static int sample() {
        String value = System.getenv("JI_STAGE6_COLD_SAMPLE");
        if (value == null || !value.matches("[1-9][0-9]*")) return 0;
        try {
            return Integer.parseInt(value);
        } catch (NumberFormatException ignored) {
            return 0;
        }
    }
}
